"Pod inbound! Reinforcements!":"Kapsul datang! Bala bantuan!",
"Anyone remember why the sky is a portal?":"Ada yang ingat kenapa langit itu portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Katanya kalau melompat ke lubang vertikal, kita muncul di tempat musuh. Aku tak mau coba.",
"The Swarm painted their visors red again. Show-offs.":"Kawanan mengecat visor mereka merah lagi. Tukang pamer.",
"Ore, ore… when do we get some oil?":"Bijih, bijih… kapan dapat minyak?",
"I dreamt I was a toaster. It was peaceful.":"Aku mimpi jadi pemanggang roti. Rasanya tenang.",
"Quiet. Too quiet.":"Sepi. Terlalu sepi.",
"See that? Our base is above the Swarm base again. Portals, man.":"Lihat itu? Markas kita lagi-lagi di atas markas Kawanan. Portal, ya ampun.",
"Diman, if you're reading this — we need a vacation.":"Diman, kalau kamu baca ini — kami butuh liburan.",
