"Browser storage is full":"Penyimpanan peramban penuh",
"Battle loaded: {0}":"Pertempuran dimuat: {0}",
"Autosaved":"Tersimpan otomatis",
"robot war · the sky is a portal":"perang robot · langit adalah portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Selamat datang di meteor! Kamu robot tempur Konsorsium. Lihat sekitar dengan mouse dan berjalan dengan WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: ketuk Shift untuk melompat, tahan Shift untuk terbang. Energi terisi ulang di tanah.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Tembak — klik kiri. Bidik — klik kanan: lebih akurat, dengan zoom. Lepaskan beberapa tembakan.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Isi ulang — R. Peluru paling kuat di jarak menengah, 20–50 meter.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Roket — Q. Untuk tank dan bangunan. Tembakkan satu roket.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Di atas ada perintah ahli strategi. Lari mengikuti panah hijau: di rute kamu berlari kencang. Rebut titik — berdiri dekat suar.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Regumu melindungimu: potret dan kesehatan mereka ada di kiri. Kalau regu tertinggal, mereka akan minta kamu menunggu.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — ganti unit cepat tanpa keluar dari pertempuran: lompat ke regu atau tank yang paling dekat dengan pertempuran. Cobalah.",
"Next to a tank or turret press E to take control. Or just carry on.":"Di dekat tank atau menara tembak, tekan E untuk mengendalikannya. Atau lanjut saja.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Sekarang strategi. Ketuk \"◩ Strategi\" di kanan atas — tampilan medan perang dari atas.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Sekarang strategi. Tekan {0} (atau \"◩ Strategi\" di kiri atas) — tampilan medan perang dari atas.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Di mode strategi, Pemandu membantumu: kotak di atas memberi tahu apa yang harus dilakukan, bingkai menunjukkan tombolnya, cincin menandai lokasi di peta. Selesaikan tiga sarannya.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Pilih satu regu lalu ketuk tombol hijau \"▶ Kendalikan\" — kembali bertempur sebagai prajurit itu. Selama kamu menembak, ahli strategi AI yang memimpin pasukan.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Pilih satu regu lalu tekan {0} atau tombol hijau \"▶ Kendalikan\" — kembali bertempur sebagai prajurit itu (tanpa pilihan — robotmu sendiri). Selama kamu menembak, ahli strategi AI yang memimpin pasukan.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Latihan selesai! Kawanan memulai serangan. Semoga berhasil, prajurit!",
"TRAINING":"LATIHAN",
"skippable in":"bisa dilewati dalam",
