"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Tampilan bijih baru: urat bijih berupa kristal zamrud berfaset yang bersinar di atas basal hitam dengan percikan dan kabut hijau; ekstraktor berupa alas segi enam dengan kubah sarang lebah dan menara kisi dengan suar hijau di puncaknya (garis dan panji berwarna tim)",
"New in v6.1":"Baru di v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Kelas pilihan seperti di Battlefield (U, angka setelah mati): kamu respawn sebagai kelas itu jika tersedia",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Kendaraan dari sudut pandang orang pertama (V — luar/kokpit); bantuan bidik ringan — di Pengaturan",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Keluar dari inti jadi mudah: Spasi — ke poros, B — kapsul ke permukaan; efek kemampuan direset saat mati",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Progres tanpa akhir: jenderal dan Marsekal ★, level karier, penguasaan senjata dan aksesori, medali, kontrak harian — layar Karier",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategi: zoom roda mulus, ikon dan label unit (Alt — semua), panel Pasukan / Bangunan di kiri",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"klik kanan — serang sambil bergerak, klik kanan 2× — maju sambil menembak; perintah jarang ada di \"Perintah lain ▾\"; tanpa tombol ganda",
"New in v6":"Baru di v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Senjata ala penembak: peluru instan, senapan 720 RPM, senapan mesin, hentakan, bidik dengan klik kanan, magasin dan isi ulang R, penanda tembakan kena",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Gravitasi lebih berat, jetpack responsif, dash dengan Z atau jetpack 2× di udara; senjata tak lagi ikut terbang saat pindah unit",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Insinyur: pilih insinyur, pilih bangunan, taruh cetak biru; Ekstraktor di urat bijih; klik \"BIJIH\" untuk lihat pemasukan dan cara menambahnya",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Tombol abu-abu bisa diklik — kami tunjukkan alasan dan solusinya; tombol lebih besar, bilah \"Sedang berjalan\", \"▶ Kendalikan\", Tab jadi satu-satunya tombol mode",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera strategi tanpa loncatan dan putaran, zoom ke kursor, minimap bisa digeser",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Kendaraan baru: perampok \"Jackal\", MLRS \"Grad\" (roket pencari sasaran), mortir \"Hammer\"; Gala mendapat \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"AI-strateg tak lagi gonta-ganti perintah dan spam suara; pertempuran datang ke arahmu; B — pindah posisi, Shift+B — ke tengah pertempuran; kompas, H — target mana",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Aksi bebas (K) dan bergerak sendiri (J), F2 — preset; Esc jeda dan lanjut; penyimpanan: slot, ekspor dan impor",
"New in v5.3":"Baru di v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Terbang: gravitasi lebih kuat jauh dari meteor, C di udara mengerem, dorongan mengarah lebih tajam; tak lagi \"nyangkut\" di portal",
"New in v5":"Baru di v5",
"Endless war by default and battle scale: normal, large, epic":"Perang tanpa akhir secara bawaan dan skala pertempuran: normal, besar, epik",
"Save and load the battle (autosave every 3 minutes)":"Simpan dan muat pertempuran (simpan otomatis tiap 3 menit)",
