"Fog of war in strategy, friends and foes outlined differently":"Kabut perang di strategi, kawan dan lawan diberi sorotan berbeda",
"Camera fly-over when switching, portal aurora instead of rings":"Kamera melintas saat berpindah, aurora portal menggantikan cincin",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Tugas sampingan, jalan pintas lewat langit, modul ekspedisi pertama berisi perbekalan, kristal, es kawah, badai debu",
