"Curator":"Kurator",
"Guides you during play: arrows to buttons and marks on the map. Turn it off any time (also in Settings).":"Memandumu selama bermain: panah ke tombol dan penanda di peta. Bisa dimatikan kapan saja (juga di Pengaturan).",
"queue {0}/5":"antrean {0}/5",
"Select the HQ and train a builder (50 ore) — click to open the HQ panel":"Pilih HQ dan latih builder (50 ruda) — klik untuk membuka panel HQ",
"Builders are trained only at the HQ: select the HQ (click it or F2) — its production panel opens on the right. Same for the mech factory, drone hub, airdock and outpost":"Builder hanya dilatih di HQ: pilih HQ (klik atau F2) — panel produksinya terbuka di kanan. Sama untuk pabrik mech, pusat drone, dok udara, dan pos terdepan",
"The Build tab opens when a builder is selected; a \"Select nearest builder\" button; Z X C V B N K pick a builder automatically":"Tab «Bangun» terbuka saat insinyur dipilih; ada tombol «Pilih insinyur terdekat»; tombol Z X C V B N K otomatis memilih insinyur",
"The Curator replaces the strategy tutorial: it suggests what to do as you play, points at the button and marks the map; turn it off on the panel or in Settings":"Kurator menggantikan tutorial strategi: memberi saran selama bermain, menunjuk tombol dengan panah dan menandai peta; matikan lewat tombol di panel atau di Pengaturan",
"Developer mode (main menu): unlimited ore, everything unlocked, instant build, the Arsenal — any weapon, class, vehicle, target dummies; your career is untouched":"Mode pengembang (menu utama): bijih tak terbatas, semua terbuka, bangun instan, Arsenal — senjata, kelas, kendaraan apa pun, target boneka; kariermu tidak berubah",
"Phone: shooter buttons no longer cover the crosshair or weapon, strategy panels collapse, bigger buttons, a clear \"Strategy ⇄ Battle\" switch":"Ponsel: tombol Penembak tak lagi menutupi bidikan atau senjata, panel strategi bisa dilipat, tombol lebih besar, pindah «Strategi ⇄ Tempur» yang jelas",
"Combined build: the v6.2 ore-vein crystals and extractors + grenades with a throw arc":"Versi gabungan: kristal dan ekstraktor urat bijih baru v6.2 + granat dengan busur lemparan",
"New in v6.4":"Baru di v6.4",
"Curator on: I will suggest what to do":"Pemandu aktif: aku akan memberi saran",
"Curator off (turn on with the \"Curator\" button or in Settings)":"Pemandu mati (aktifkan lewat tombol «Pemandu» atau Pengaturan)",
"BUILDER":"INSINYUR",
"VEIN ⛏":"URAT ⛏",
"ENEMY":"MUSUH",
"Select a builder: the \"⚒ Select nearest builder\" or \"⚒ Builder\" button.":"Pilih insinyur: tombol «⚒ Pilih insinyur terdekat» atau «⚒ Insinyur».",
"Select a builder: \"⚒ Select nearest builder\" on the right or click one.":"Pilih insinyur: «⚒ Pilih insinyur terdekat» di kanan atau klik insinyurnya.",
"Tap the marked vein ⛏ (glowing crystals), then \"✔ Build\". Mark off-screen — tap it to fly the camera there.":"Ketuk urat bertanda ⛏ (kristal bercahaya), lalu «✔ Bangun». Penanda di luar layar — ketuk agar kamera terbang ke sana.",
"Click the marked vein ⛏ — the glowing crystals (RMB/Esc — cancel). Mark off-screen — click it to fly the camera there.":"Klik urat bertanda ⛏ — kristal bercahaya (klik kanan/Esc — batal). Penanda di luar layar — klik agar kamera terbang ke sana.",
"Tap a spot for the {0}, then \"✔ Build\".":"Ketuk lokasi untuk «{0}», lalu «✔ Bangun».",
"Click a spot for the {0} (RMB/Esc — cancel).":"Klik lokasi untuk «{0}» (klik kanan/Esc — batal).",
"I am the Curator: I highlight the button and the spot on the map. \"✕\" turns me off.":"Aku Pemandu: aku menyorot tombol dan lokasi di peta. «✕» — matikan.",
"I am the Curator. I will suggest what to do as you play, highlighting the button and the spot on the map. Turn me off with \"✕\" here or the \"Curator\" button at the bottom right.":"Aku Pemandu. Aku akan memberi saran selama bermain, menyorot tombol dan lokasi di peta. Matikan lewat «✕» di sini atau tombol «Pemandu» di kanan bawah.",
"The Swarm is at the base! \"All army\", then long-tap the enemies. A turret at the base helps too.":"Kawanan di markas! «Seluruh pasukan», lalu ketuk lama pada musuh. Menara tembak di markas juga membantu.",
"The Swarm is at the base! Select troops (box or Ctrl+A) and RMB the enemies. A turret (Z) helps too.":"Kawanan di markas! Pilih pasukan (kotak atau Ctrl+A) dan klik kanan pada musuh. Menara tembak (Z) di markas juga membantu.",
"Camera: drag the map with a finger, two fingers — zoom and rotate. Move the camera.":"Kamera: seret peta dengan jari, dua jari — zoom dan putar. Geser kamera.",
"Camera: WASD or screen edges, wheel — height, Q/E — rotate. Move the camera.":"Kamera: WASD atau tepi layar, roda — ketinggian, Q/E — putar. Geser kamera.",
"No builders — and nothing gets built without them. Select the HQ — click it or the \"⌂ HQ\" button.":"Tak ada insinyur — tanpa mereka tak ada bangunan yang bisa dibuat. Pilih Markas — klik atau tombol «⌂ Markas».",
"Order a builder — the \"⚒ Builder\" button in the HQ panel (50 ore).":"Pesan insinyur — tombol «⚒ Insinyur» di panel Markas (50 bijih).",
"We need ore — let us put an extractor on an ore vein.":"Butuh bijih — kita pasang ekstraktor di urat bijih.",
"Press \"Extractor\" (C) and place it on the glowing crystals of the vein — I marked it ⛏.":"Tekan «Ekstraktor» (C) dan taruh di kristal bercahaya pada urat — sudah kutandai ⛏.",
"Few troops. Select the HQ — squads are ordered there.":"Pasukan sedikit. Pilih Markas — regu dipesan di sana.",
"Order an \"Assault squad\" in the HQ panel.":"Pesan «Regu serbu» di panel Markas.",
"Points give ore. Select a squad — tap it or the \"◈ Squad\" button on the right.":"Titik menghasilkan bijih. Pilih regu — ketuk regu atau tombol «◈ Regu» di kanan.",
"Points give ore. Select a squad — tap it or the \"◆ Army\" card at the top.":"Titik menghasilkan bijih. Pilih regu — ketuk regu atau kartu «◆ Pasukan» di atas.",
"Points give ore. Select a squad — click it or its card in the \"◆ Army\" panel on the left.":"Titik menghasilkan bijih. Pilih regu — klik regu atau kartunya di panel «◆ Pasukan» di kiri.",
"Long-tap point {0} — the squad goes to capture it.":"Ketuk lama titik {0} — regu pergi merebutnya.",
"RMB on point {0} — the squad goes to capture it.":"Klik kanan titik {0} — regu pergi merebutnya.",
"POINT ":"TITIK ",
"The base is under attack — let us build a turret.":"Markas diserang — kita pasang menara tembak.",
"Press \"Turret\" (Z) and place it at the base, facing the enemy.":"Tekan «Menara tembak» (Z) dan taruh di markas, menghadap musuh.",
"Enough ore for a mech factory — it makes tanks and vehicles.":"Bijih cukup untuk pabrik mech — membuat tank dan kendaraan.",
"Press \"Mech factory\" (B) and place it at the base (a flat spot inside the dashed ring).":"Tekan «Pabrik mech» (B) dan taruh di markas (tempat datar di dalam cincin putus-putus).",
"{0} is idle — select it and give an order: {1} a point or an enemy.":"{0} menganggur — pilih dan beri perintah: {1} titik atau musuh.",
"The mech factory is ready. Select it to order a tank.":"Pabrik mech siap. Pilih untuk memesan tank.",
"Order a \"Tank\" in the factory panel.":"Pesan «Tank» di panel pabrik.",
"More extractors — more ore. There is a free vein nearby.":"Lebih banyak ekstraktor — lebih banyak bijih. Ada urat bebas di dekat sini.",
"\"Extractor\" (C) on the marked vein ⛏.":"«Ekstraktor» (C) di urat bertanda ⛏.",
"Pick a power and click an enemy cluster.":"Pilih serangan dan klik kerumunan musuh.",
"Command points are piling up — the \"✺ Powers\" tab: artillery, recon, drop pod.":"Poin komando menumpuk — tab «✺ Serangan»: serangan artileri, pengintaian, kapsul pendarat.",
"Low on ore? Tap \"ORE\" at the top — see where income comes from and how to boost it.":"Bijih menipis? Ketuk «BIJIH» di atas — lihat dari mana pemasukan dan cara menambahnya.",
"Want to fight yourself? Select a squad and press \"▶ Possess\".":"Mau bertempur sendiri? Pilih regu dan tekan «▶ Kendalikan».",
