"Panel":"Panel",
"Battle":"Ke medan tempur",
"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Penembak berat Konsorsium kini model 3D berkerangka sungguhan: diam, berjalan, berlari membawa senjata, menembak sambil bergerak, dan jatuh saat hancur",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Model berdiri sesuai normal permukaan meteor, memutar badan mengikuti bidikan, dan memegang senapan mesin; di kejauhan animasi diperbarui lebih jarang agar FPS tetap stabil",
"New in v6.5":"Baru di v6.5",
"Barracks":"Barak",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Infanteri: regu serbu, penembak berat, penembak jitu, pengintai, kapsul pendarat; peningkatan armor dan senjata.",
"Ore depot":"Depot bijih",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Insinyur menyetor kristal di sini. Letakkan di dekat ladang kristal — jarak angkut lebih dekat, bijih lebih banyak.",
"Tanks and vehicles. Requires Barracks.":"Tank dan kendaraan. Butuh Barak.",
"Autonomous combat drones. Requires Barracks.":"Drone tempur otonom. Butuh Barak.",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Jetpack II dan Pasukan langit (elite jetpack). Butuh pabrik mech, terbuka pada 6:00.",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"Markas depan di titik milikmu: insinyur, setor kristal, bala bantuan.",
