"Limit reached":"Batas tercapai",
"Unlocks in {0}":"Terbuka dalam {0}",
"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"Jetpack dan pesawat terbuka belakangan — sempatkan pasang pertahanan antipesawat dan menara tembak. Sementara itu bangun Barak dan pabrik mech.",
