"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"Tambang kristal: insinyur mengambil muatan di ladang hijau dan membawanya ke Markas/depot. Atau klik kanan kristalnya.",
