"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → \"Pengendalian\": aktifkan \"Urutan kustom\" dan tentukan siapa yang kamu ambil setelah mati — #1, #2… ✕ berarti jangan pernah.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → jeda → \"Urutan kustom\": tentukan siapa yang kamu ambil setelah mati dan saat menekan X — #1, #2… ✕ berarti jangan pernah.",
