"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Ketuk \"Bidik\" untuk memperbesar. Ketuk lagi untuk kembali.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Regumu mengikutimu. Buka ☰ → \"Jeda\" → petak \"Regu bersamaku\" — berubah jadi \"Bertindak sendiri\".",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Insinyur terpilih — ketuk \"◆ Tambang kristal\" di kartunya di bawah (atau ketuk kristal hijau).",
