"steps":"langkah",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Kamu bisa membangun markas, memesan pasukan, memberi komando, dan terjun ke pertempuran. Selanjutnya — pertandingan sungguhan: Kurator akan membantu selama bermain.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Kamu bisa bergerak, terbang, menembak, berlindung, dan memberi komando regu. Selanjutnya — pertandingan sungguhan.",
