"you are on a phone: touch screen":"kamu pakai ponsel: layar sentuh",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Arena pasir yang aman: musuh hanyalah manekin, tak ada yang menembakmu. Langkah dihitung hanya saat kamu benar-benar melakukan aksinya.",
"Show others (training for the other device)":"Tampilkan lainnya (latihan untuk perangkat lain)",
"Old training (v7.1)":"Latihan lama (v7.1)",
"Back to the normal device mode":"Kembali ke mode perangkat normal",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Latihan untuk perangkat lain akan memuat ulang halaman dalam mode perangkat itu (PC — mouse dan keyboard, ponsel — sentuhan; di PC sentuhan bisa diuji di Chrome: F12 → ikon ponsel).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Latihan ×4: pelajaran \"Strategi\" dan \"Penembak\" langkah demi langkah yang terpisah untuk PC dan ponsel. Sandbox aman dengan manekin, tombol yang tepat disorot, panah, serta tombol, mouse, dan gestur beranimasi; langkah hanya dihitung jika kamu melakukan aksi yang benar, ada \"ulangi langkah\", progres di atas, dan hadiah di akhir",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Menu Latihan otomatis menampilkan pelajaran untuk perangkatmu; \"Tampilkan lainnya\" — keempatnya di perangkat apa pun; \"Latihan lama (v7.1)\" masih tersedia",
"New in v7.2":"Baru di v7.2",
"NEW IN v7.2":"BARU DI v7.2",
"No grenades left":"Granat habis",
"Rocket and grenade recharging · {0} s":"Roket dan granat sedang diisi ulang · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Kiri — bergerak, kanan — melihat · ketuk musuh — roket / granat · 2 ketukan — refleks · 3 ketukan — serangan artileri",
"Less":"Lebih sedikit",
"More":"Lebih banyak",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Ada kendaraan atau bangunan musuh di dekat — ketuk: roket meluncur.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Banyak musuh — ketuk dua kali di tempat kosong di kanan: refleks memperlambat waktu.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Bidik gerombolan musuh dan ketuk 3 kali — serangan artileri.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Jari kiri — bergerak, jari kanan — melihat. Menembak otomatis saat membidik musuh.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ di tepi kiri — jetpack: ketuk untuk melompat, tahan untuk terbang.",
"Old v7.2 layout":"Tata letak lama v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Geser jari di separuh layar kanan — joystick melihat muncul di bawah jarimu.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Sentuh sisi kiri dan geser — joystick muncul di bawah jarimu. Capai penanda hijau.",
"Hold the \"Jet\" button at the left edge.":"Tahan tombol \"Jet\" di tepi kiri.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Bidik target latihan dengan joystick kanan — prajuritmu menembak otomatis saat bidikan mengenainya.",
"Tap the dummy on the screen — a rocket flies.":"Ketuk target latihan di layar — roket meluncur.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Ketuk target latihan — granat melayang melengkung, tepat ke sasaran.",
"Double tap an empty spot on the right quickly.":"Ketuk dua kali dengan cepat di tempat kosong di kanan.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Mode ringan untuk ponsel lemah: resolusi lebih rendah, tanpa bayangan atau distorsi, bot dan partikel setengahnya, batas 30 FPS; menurunkan resolusi sendiri jika FPS < 25. Aktif secara default di ponsel (Pengaturan → Grafis → \"Mode ringan\"; atau ?lite=1 / ?lite=0 di tautan).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Ponsel: kontrol baru. Kiri — bergerak, kanan — melihat (kedua joystick muncul di bawah jarimu). Hanya jari kiri — \"otomatis\"; saat jari kanan dipakai, prajurit menembak sendiri hanya saat bidikan mengenai musuh. Ketuk musuh — roket atau granat, 2 ketukan — refleks, 3 ketukan — serangan artileri. Isi ulang otomatis. Jetpack — tombol di tepi kiri. Sudut bawah kosong, minimap di sudut, petunjuk bisa ditutup dengan tanda silang, misi bisa dilipat. Tata letak lama: Pengaturan → Ponsel.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Petunjuk (pop-up dan pemandu) — satu sakelar di pengaturan. Kamu bermain sebagai siapa (jenis prajurit atau kendaraan) — label \"Kamu: …\" di HUD. Teropong senapan dan senapan mesin transparan. Panel \"Gudang senjata\" menempel di kanan, bisa dilipat dan dimatikan. Mode \"Solo tanpa regu\" (J) dihapus. Suara strategis tidak lagi mengulang kalimat yang sama. Tank punya indikator menara terhadap lambung. Kursor tidak lagi hilang di awal latihan strategi.",
