"Voice of hints & curator":"Suara petunjuk & pemandu",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Ponsel: tiga mode stik. Hanya kiri — \"otomatis\" (magnet kuat, peluru lebih lemah). Hanya kanan — bidikan menyala sendiri, magnet lebih kuat, tembakan lebih akurat. Keduanya — tanpa bidikan, magnet dan akurasi lebih rendah. Tombol 👁 di kanan menyembunyikan/memunculkan antarmuka.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Ponsel: strategi disederhanakan — hanya insinyur dan bangunan. Kartu di kiri (insinyur, Markas, Barak…): ketuk — kamera terbang ke sana, bilah bawah langsung menampilkan apa yang bisa dibangun/diproduksi. \"Ke medan perang\" — kiri atas. Pasukan bertarung sendiri. Strategi penuh — Pengaturan → Ponsel.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Kendali — dua sakelar: \"Regu\" dan \"Kendaraan\" (kendaraan nonaktif secara default di ponsel — AI yang mengemudikannya). Jika kendaraan nonaktif, E (ponsel: tombol di kanan) di dekat kendaraan sekutu — duduk di meriamnya: kendaraan melaju sendiri, kamu menembak. Urutan kelas kustom yang lama ada di \"Lanjutan\". Unit menjawab lewat radio saat kamu mengendalikannya.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Petunjuk pintar: petunjuk dasar padam sendiri setelah peluncuran ke-2, tapi game tetap menunjukkan fitur yang belum pernah kamu pakai. Sakelar: dasar / lanjutan / langka, dan terpisah — suara petunjuk dan pemandu.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks terisi dari pembunuhan (beruntun — lebih banyak). Rekan regu tertinggal atau tewas — ahli strategi menerjunkan yang baru ke arahmu (lebih mahal daripada bala bantuan biasa). Grafis dan suara v7.2gfx sudah digabung: ledakan berkepul, asap, puing, akustik poros dan kawah. Tanggal build kini asli.",
