"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karier dan simpanan tidak berubah. Dalam pertempuran, menu yang sama adalah tombol \"🛠 Menu\" di kanan atas{0}.",
