"both bases built and upgraded — for footage":"kedua markas dibangun dan ditingkatkan — untuk pengambilan gambar",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Mode sinema — layar terbelah: bot Strategist di kiri (tampak atas markas dan pasukan), bot Shooter di kanan dari sudut pandang orang pertama. Tombol di bawah (tombol S, P): \"Layar terbelah\" dan \"★ Semua dibangun\" — kedua markas dibangun dan ditingkatkan untuk pengambilan gambar.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Inti dan terowongan yang menembus meteor sudah tidak ada — meteornya padat, pertempuran hanya terjadi di permukaan.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Ponsel: 👁 menyembunyikan HUD tetapi tetap menampilkan jetpack, ⇆, stik, dan penanda tujuan. \"◎ Bidik\" (hanya jari kanan) — magnet yang jauh lebih kuat dan lebih lebar; kekuatan magnet untuk ketiga mode ada di Pengaturan → Kontrol → \"Lanjutan\". Di meriam kendaraan, tombolnya bertuliskan \"Turun\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Latihan: ponsel hanya menampilkan latihan ponsel, PC hanya latihan PC. Keempatnya ada di menu \"🛠 Pengembang\". Mode pengembang dan Arsenal kini satu menu (dalam pertempuran — \"🛠 Menu\" di kanan atas, F8 di PC).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Gaya grafis \"Dendy (8-bit)\" dan \"16-bit\": Pengaturan → Grafis → \"Gaya grafis\" (detail — tombol ⚙). Jika FPS di bawah 24 pada ~10 dtk pertama pertandingan, Dendy aktif sendiri (di bawah 20 — piksel lebih besar, 120 baris); notifikasi \"kembali normal\" memulihkan grafis normal untuk seterusnya. Pilihanmu sendiri di menu selalu diutamakan.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Model lingkungan 3D (reruntuhan, bangkai kendaraan, benteng) — hanya yang berperingkat bagus, dimuat sesuai kebutuhan. Matikan: Pengaturan → Grafis → \"Model lingkungan 3D baru\".",
