"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Trooper bisa membangun: E (ponsel: \"Masuk\") di lokasi bangun milik sendiri — trooper-mu yang membangun, rekan squad di dekatnya membantu. Jika para engineer sibuk, Strategist meminta bantuanmu — dengan penanda \"LOKASI BANGUN\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Tanda Strategist: Strategist menaruh ⌖ pada kerumunan musuh di dekatmu — artileri menghantam 8 dtk kemudian, dan MLRS \"Grad\" kawan di sekitar menembakkan salvo. Serangan artileri dari mode strategi milikmu juga mendapat dukungan \"Grad\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Gudang senjata di kontainer kargo dan satelit yang jatuh (📦 terlihat dari 70 m): E — senapan mesin berat selama 90 dtk, peluru api atau roket, plus granat penuh. Merayap: Ctrl — tiarap / berdiri (lebih rendah, lebih tenang, lebih akurat, tetapi lambat).",
