"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Main sekarang\" — tombol pertama di menu: terbang singkat di bawah langit portal dan langsung ke pertempuran (lewati dengan tombol apa saja atau ketukan).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Tembakan terasa nyata: suara logam dan percikan api, penanda kill di bidikan (tembakan kepala — kuning), rentetan ×N, guncangan halus dari ledakan, slow motion pada kill penting. Guncangan, slow motion, dan petunjuk bisa dimatikan di Pengaturan.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Hasil pertandingan: waktu, kill, rentetan terbaik, ★ MVP dan regu terbaik, kartu pertandingan — \"⇪ Bagikan\", PNG atau tautan ke game.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Petunjuk \"apa yang harus dilakukan sekarang\" di kiri di bawah sumber daya: perintah ahli strategi, titik rebut, serangan Kawanan. ✕ atau F7 — ciutkan.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Pertempuran tersimpan otomatis saat kamu menutup atau menyembunyikan tab — \"⟲ Lanjutkan\" di menu.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 tetap ada di menu \"🕘 Versi game\" kalau kamu lebih suka. Statistik anonim (tanpa nama atau email) kini dikirim; matikan di Pengaturan.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Main sekarang\", umpan balik tembakan, hasil pertandingan dengan kartu bagikan, petunjuk \"apa yang harus dilakukan\", simpan otomatis",
"and older: v7.5, v7.4, milestones v1–v7.0":"dan yang lebih lama: v7.5, v7.4, tonggak v1–v7.0",
"New in v7.6":"Baru di v7.6",
"NEW IN v7.6":"BARU DI v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Pilih faksimu sebelum pertandingan: \"Konsorsium\" (infanteri berat berbaju zirah bertenaga, zirah dan artileri) atau \"Kawanan\" (kecepatan, kawanan drone, tembakan berat dengan distorsi). AI memainkan yang lain. Pilihanmu diingat.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Tiap faksi punya kendaraan dan keunikan sendiri: Konsorsium — tank \"Rinoceronte\" dan \"Pelat keramit\", Kawanan — \"Kawanan drone\" dan \"Jetpack fase\". Keseimbangan diuji lewat pertandingan antar-bot.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Kawah ledakan: artileri, roket, dan meriam tank menggali lubang di meteor — kamu bisa berjalan dan berkendara melewatinya, dan berlindung di dalamnya.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Sudut pandang orang ketiga untuk prajurit (V, tersimpan; di ponsel — Kontrol) dan kamera kendaraan yang halus dengan penanda tempat meriam akan mengenai sasaran.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 tetap ada di menu \"🕘 Versi game\" kalau kamu lebih suka versi itu.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Faksi Konsorsium / Kawanan dengan pilihan sebelum pertandingan, kawah ledakan, sudut pandang orang ketiga",
"and older: v7.6, v7.5, milestones v1–v7.0":"dan yang lebih lama: v7.6, v7.5, tonggak v1–v7.0",
