"Anomaly ahead — it is crackling with current!":"Anomali di depan — berderak penuh arus listrik!",
"Rods and lightning — a Crackler. It loves armour!":"Batang dan petir — Penderak. Dia suka armor!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomali! Tanah bergetar karena panas — Perapian!",
"Careful, a Brazier underfoot!":"Hati-hati, ada Perapian di bawah kaki!",
