"Supply drop":"Pasokan jatuh",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Menjatuhkan peti di dekat pasukanmu: amunisi, granat, roket, suku cadang senjata, paket perbaikan.",
"\"Grad\" rocket strike":"Serangan roket \"Grad\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 roket ke area luas setelah 3 detik — lebih cepat dan lebih lebar daripada serangan artileri.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Dukungan: peti, pengintaian, \"Grad\", serangan artileri (lalu 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"PERHATIAN: \"Grad\" Kawanan mengarah ke areamu!",
"Warning! Rocket salvo on our position!":"Awas! Rentetan roket menuju posisi kita!",
"take the supply crate":"ambil peti pasokan",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomali di meteor (gelombang 1): \"Veta Cantora\" — kristal hijau berpendar yang berdengung dan menghantam semua yang di dekatnya dengan denyut berirama; \"Pusaran\" menarik dan membanting, \"Penderak\" menyambar di antara batang, \"Perapian\" menyala di bawah kaki, \"Kabut asam\" dan \"Lensa\" (membelokkan peluru dan pandanganmu) melayang-layang.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomali bisa dirasakan sebelumnya (dengungan, cahaya, kabut panas). Lepaskan muatannya dengan granat, roket, atau baut (E di dekatnya): dia akan tidur, kadang meninggalkan artefak dengan sisi plus dan minus. Regumu memperingatkan lewat radio, dan musuh (juga kawan) kadang tersesat ke dalamnya — pancing mereka!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Dukungan dengan poin komando: 4 saat bertempur (📡 di ponsel) — pasokan jatuh, pemindaian pengintaian, serangan roket \"Grad\", artileri di bidikan. Strateg hanya melihat anomali di peta setelah pemindaian.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Peti pasokan ada di reruntuhan ekspedisi lama, dekat QG, dan di samping bangunan yang sudah jadi: amunisi, granat, roket, suku cadang senjata (membuka aksesori).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 tetap ada di menu \"🕘 Versi game\". Anomali bisa dimatikan di Pengaturan.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomali (\"Veta Cantora\" dan 5 lainnya), melepas muatan dengan baut atau granat, artefak, panggilan dukungan dengan PK, peti pasokan",
"and older: v7.7, v7.6, milestones v1–v7.0":"dan yang lebih lama: v7.7, v7.6, tonggak v1–v7.0",
"New in v7.8":"Baru di v7.8",
"NEW IN v7.8":"BARU DI v7.8",
"Close":"Tutup",
"Anomalies on the meteor":"Anomali di meteor",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ di pojok membuka menu jeda: Lanjutkan, Mulai ulang, Latihan, Grafis, Pengaturan, Menu utama (dengan konfirmasi). Ponsel: ☰ di kanan atas (aksi pertempuran — ubin \"⚡ Aksi\"); PC: tombol \"☰ Menu\" di kanan atas atau Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafis selalu normal secara default — Dendy hanya jika kamu memilihnya: sakelar \"Grafis: Normal / Dendy (8-bit) / 16-bit\" ada langsung di menu utama dan menu jeda. Jika game sangat lag, muncul saran dengan tombol \"Aktifkan Dendy\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Ponsel dan tablet: tombol aksi \"✋\" di kanan hanya muncul saat ada yang bisa dilakukan di dekat sini — \"Ambil\" (cache, peti), \"Naik\" (kendaraan, menara tembak, meriam), \"Bangun\", \"Turun\", \"Baut\" di anomali. Kamu juga bisa langsung mengetuk objek yang menyala.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Ponsel, strategi: tahan jari ~0,3 dtk (ponsel bergetar, muncul cincin kuning) lalu seret — kotak pilihan; geser biasa menggerakkan kamera. Ada juga tombol \"Kotak\" di kanan; di latihan, langkah \"Kotak\" juga menerima ketukan pada sebuah regu.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Ponsel: tombol kecil lebih mudah ditekan, daftar dukungan 📡 lebih besar, panel strategi tidak lagi menutupi layar jeda dan hasil. v7.8 tetap ada di menu \"🕘 Versi game\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menu ☰ di ponsel dan PC, tanpa Dendy otomatis, tombol \"✋\" di layar sentuh, pilih kotak di ponsel",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Lag? Coba grafis Dendy — lebih ringan.",
"Turn on Dendy":"Aktifkan Dendy",
"Use":"Gunakan",
"Man gun":"Pakai meriam",
"Board":"Naik",
"Man it":"Pakai",
