"Quit to the main menu?":"Keluar ke menu utama?",
"The training starts from step one.":"Latihan akan dimulai dari langkah pertama.",
"The current battle ends and a new match starts with the same settings.":"Pertempuran saat ini berakhir dan pertandingan baru dimulai dengan pengaturan yang sama.",
