"Commander — still in development":"Komandan — masih dalam pengembangan",
"Pause: resume, restart, training, graphics, settings, main menu":"Jeda: lanjutkan, mulai ulang, latihan, grafis, pengaturan, menu utama",
"Menu: pause, restart, training, graphics, settings":"Menu: jeda, mulai ulang, latihan, grafis, pengaturan",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Tahan jari di tanah ~0,3 dtk — ponsel bergetar dan muncul cincin kuning — lalu, tanpa melepas, seret: akan muncul kotak. Atau pakai tombol \"Kotak\" di kanan. Mengetuk sebuah regu saja juga bisa.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Untuk layar penuh di iPhone: \"Bagikan\" ⬆ → \"Tambah ke Layar Utama\" — game terbuka tanpa bilah Safari.",
"Open portal-meteor.pages.dev for that.":"Untuk itu, buka portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Ketuk — pilih · ketuk tanah — gerak · tahan — menu perintah · tahan dan seret — kotak · 2 jari — zoom",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Pahlawan pembunuh: dash-teleport, katana, shuriken. Berteleportasi sendiri melewati zona musuh dan mencabik robot. 1 per pihak.",
"Shadow protocol":"Protokol Bayangan",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Riset: membuka robo-ninja di Barak. Butuh Pabrik mech yang sudah jadi.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Pahlawan (1 per pihak): berteleportasi sendiri melewati zona musuh dan mencabik robot; ambil alih untuk bermain manual.",
"is ready. She works on her own (AUTO) — possess her to play manually":"siap. Dia bekerja sendiri (OTO) — ambil alih untuk bermain manual",
"Robo-ninja ready for action":"Robo-ninja siap bertempur",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Intel: musuh punya robo-ninja!",
"Warning! The enemy has a robo-ninja. Stay together":"Awas! Musuh punya robo-ninja. Tetap berkelompok",
