"order":"perintah",
"nearby":"di dekat sini",
"Zone cleared":"Zona bersih",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DUEL NINJA! Blok tepat sebelum serangan untuk menangkis, dash untuk menghindar. Perhatikan kilatan sebelum serangan",
"The two ninjas have met in a duel!":"Dua ninja bertemu dalam duel!",
"⚔ Duel won! Our ninja prevails":"⚔ Duel dimenangkan! Ninja kita unggul",
"⚔ Duel lost…":"⚔ Duel kalah…",
