"POSTURE BROKEN":"KUDA-KUDA PATAH",
"Teleport":"Teleportasi",
"Teleport: aim at the ground (up to 150 m)":"Teleportasi: bidik ke tanah (hingga 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ OTO: dia melompat melewati zona musuh dan menebas sendiri. Stik / WASD menjeda selama 1.5 dtk",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Manual: ketuk musuh — dash & tebas, geser — tebas, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Manual: klik kiri — katana, klik kanan — blok, Shift — dash, Q — shuriken, G — teleportasi",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: ketuk musuh — melesat & menebas, geser di kanan — tebas, ● — serang, 🛡 — blok (tepat waktu = tangkis), ⇑ — lesatan, ✦ — shuriken, ◎ — teleportasi, AUTO — bergerak sendiri",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: klik kiri — katana (tahan — tebasan berat), klik kanan — blok (tepat waktu = tangkis), Shift/Z — lesatan, Q — shuriken, G — teleportasi ke bidikan, lompat di udara — lompat ganda / lari di dinding, {0} — AUTO",
"Robo-ninja: AUTO on/off":"Robo-ninja: AUTO nyala/mati",
