"Radio: start by itself in battle":"Radio: nyala sendiri saat bertempur",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: cyborg bersenjata katana. Dibuka di Barak lewat riset \"Protokol Bayangan\" (butuh Pabrik Mech). Berteleportasi sendiri ke zona musuh, mencincang musuh (tanpa darah — hanya percikan api), melesat, melempar shuriken, berduel dengan ninja musuh. Kendalikan dia — mode AUTO atau kendali manual (di ponsel ada tombol sendiri).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 lagu EDMITRY langsung di dalam game. Tombol 5 (bisa diubah), di ponsel — ☰ → Pengaturan → Suara. Volume dan \"nyala sendiri saat bertempur\" ada di pengaturan; musik mengecil saat ledakan dan suara radio.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Bahasa baru: Uzbek dan Tajik — lengkap; Mandarin, Spanyol, Portugis — sebagian. Pemilih bahasa baru di menu, di samping \"Pertandingan baru\".",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Ponsel: \"sembunyikan ikon\" 👁 merapikan tombol yang tersisa dalam satu kolom di tepi kanan; mode potret tidak lagi bertumpuk; iPhone — game tidak lagi berbenturan dengan gestur Safari, dan \"Bagikan → Tambah ke Layar Utama\" membukanya layar penuh.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Dari v7.8.1: menu sudut ☰ (jeda, ulang, latihan, grafis), tanpa Dendy otomatis, tombol aksi ✋ di ponsel. v7.8.1 dan v7.8 tetap ada di menu \"🕘 Versi game\".",
