"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konsorsium. Bos: lambung 15000, meriam, 2 senapan mesin, roket. Sangat lambat. Titik lemah — bagian belakang. Satu per pasukan.",
