"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Kawanan. Bos: lambung 12500, sinar distorsi, injakan. Melangkahi barikade. Titik lemah — inti di bawah perut. Satu per pasukan.",
