"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Kawanan. Regu dalam jarak 70 m dari liang (dan yang terpilih), serta kendaraan ringan/menengah terpilih (Anjing Hutan, Palu, Grad), melewati terowongan dan keluar di ujung lain. Atau: pilih lalu klik kanan/ketuk liang.",
