"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Pilih satu unit → \"▶ Kendalikan\" atau ketuk dua kali. Tombol mode di kanan atas: Strateg → Komandan → Penembak.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Pilih satu unit → \"▶ Kendalikan\" atau klik dua kali. {0} bergilir: Strateg → Komandan → Penembak.",
