"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Unitmu meminta bantuan dan memberi imbalan, pahlawan memberi misi, front yang macet dipecahkan lewat operasi",
"A request":"Permintaan",
"Breakthrough":"Terobosan",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Unit-mu kadang meminta bantuan: suara lewat radio, kartu PERMINTAAN, dan penanda ✋. Satu regu terjepit — hancurkan musuh di dekatnya. Hadiah: prajurit via kapsul dari markas, senjata dari bak belakang buggy, kursi penembak, atau perlindungan orbital. Tak mau — ✕ atau abaikan saja.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Pengintai veteran \"Burung Hantu\" menawarkan misi. Y — terima (N — tolak). Pergi ke penanda ★, bereskan penjaga, lalu berdiri di dekat pilot selama 3 s — dia bergabung ke regumu.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Front macet — markas menawarkan terobosan. Y — terima. Kuasai relai selama 8 s tanpa musuh di dekat: peta musuh terlihat 60 s. Generator — menara tembak musuh bungkam 2 menit. Di Ahli Strategi — \"Tugaskan regu\". Musuh juga bisa melakukannya: waspadai ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Unitmu meminta bantuan: kartu PERMINTAAN dan penanda ✋. Hancurkan musuh di dekat regu yang terjepit — dapatkan hadiah. ✕ — lewati.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Pahlawan \"Burung Hantu\" menawarkan misi — ketuk \"Terima\". Pergi ke ★, bereskan penjaga, berdiri di dekat pilot.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Front macet — ketuk \"Terima\" dan kuasai relai selama 8 s: peta musuh terbuka selama semenit.",
"Pod redeploy from the base: {0} m — through the sky portal":"Pemindahan via kapsul dari markas: {0} m — lewat portal langit",
