"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Membangun bangunan dan Ekstraktor, memperbaiki, membersihkan Bulu baja dari rekan.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Satu regu terbang dari landasan peluncuran markas melalui portal langit langsung ke target.",
"Squad: ":"Regu: ",
"Engineer":"Insinyur",
"Members: ":"Anggota: ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Tank tempur utama: meriam dan senapan mesin. \"Bulldog\" milik Konsorsium lebih tangguh, \"Spider\" milik Gerombolan lebih cepat.",
"Heavy tank":"Tank berat",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Penembak terbang otonom: cepat, rapuh, takut meriam antipesawat.",
"Upgrade":"Peningkatan",
"Longer, faster jetpacks for all infantry.":"Jetpack lebih jauh dan lebih cepat untuk semua infanteri.",
"Extractors mine more ore.":"Ekstraktor menambang lebih banyak bijih.",
"Army-wide levels: less damage taken / more damage dealt.":"Level untuk seluruh pasukan: kerusakan diterima lebih kecil / kerusakan ke musuh lebih besar.",
"Levels":"Level",
"Base":"Markas",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Jantung markas: regu, insinyur, kapsul, riset. Kehilangannya berarti kalah.",
"Produces: ":"Memproduksi: ",
"Launch pad":"Landasan peluncuran",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silo di samping Markas: kapsul, peti suplai, dan pembom diluncurkan dari sini melalui portal langit. Tidak bisa dibangun di atasnya.",
"Economy":"Ekonomi",
"Key building":"Bangunan kunci",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Titik lemah — bagian belakang (mesin): kerusakan ×{0}. Meriam, 2 menara senapan mesin, pod roket; berputar sangat lambat — serang dari samping.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Titik lemah — inti bercahaya di bawah perut: kerusakan dari bawah ×{0}. Sinar distorsi dan injakan area; melangkahi barikade — jaga jarak, jangan bergerombol.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Lawan: bom udara dan artileri (×{0}), roket (×{1}), pengeboman karpet; peluru nyaris tak berguna (×{2}).",
"Faction":"Fraksi",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Mesin cepat, kawanan drone, terowongan, dan regenerasi. Infanteri lebih ringan tapi lebih cepat; meriam dan rel lebih kuat.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Infanteri berat berbaju zirah bertenaga, barikade beton, perbaikan, dan artileri. Lebih lambat tapi lebih tangguh.",
"Infantry HP":"HP infanteri",
"Infantry speed":"Kecepatan infanteri",
