"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Mainkan dan bicara sambil bermain: apa yang membingungkan, menjengkelkan, seru. Di pojok layar tampil versi, waktu, dan FPS — dengan itu rekaman dicocokkan dengan catatan.",
