"Want to command the army?":"Mau memimpin pasukan?",
"Unlock the Strategist mode: look from above and give orders to the whole army.":"Buka mode Strategis: melihat dari atas dan memberi perintah ke seluruh pasukan.",
"Want to lead one squad?":"Mau memimpin satu regu?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"Buka mode Komandir: kamera di atas regu, ketuk tempat tujuan.",
"Yes":"Ya",
"Later":"Nanti",
"You run and shoot yourself. That is how you have played so far.":"Kamu sendiri yang berlari dan menembak. Begitulah caramu bermain sampai sekarang.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Melihat dari atas dan memimpin seluruh pasukan: membangun markas, mengirim regu. Pasukan juga bertempur sendiri.",
"You lead one squad: the camera is above it, tap the ground to move.":"Memimpin satu regu: kamera di atasnya, ketuk tanah untuk menentukan tujuan.",
