"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"Petunjuk disembunyikan — ketuk «?» untuk membukanya lagi. Untuk keluar dari pelajaran: ☰ → «Keluar dari pelajaran»",
"◎ precise":"◎ presisi",
"○ running":"○ lari",
"◉ run + aim":"◉ lari + bidik",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"Mode Komandan, bos faksi, meteor yang hidup (medan, bioma, cuaca, anomali, fauna), dunia yang hidup; lebih cepat, gamepad, tablet, ensiklopedia, mode umpan balik, antarmuka ponsel yang sederhana",
"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Tiga mode dengan satu tombol: Penembak (kamu sendiri di pertempuran), Komandir baru (memimpin satu regu, 4 kemampuan per tipe unit) dan Strategis. Di ponsel — antarmuka sederhana: tombol lebih sedikit, mode terbuka seiring pertempuran.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Meteor yang hidup: tebing, punggung bukit, hanggar di dalam mesa, danau lava / es / metana, tiga bioma, cuaca lokal, anomali baru, dan fauna asli.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Faksi kini berbeda gaya: Swarm menggali terowongan dan beregenerasi, Konsorsium membangun barikade dan memperbaiki peralatan. Mulai menit ke-12 — bos \"Bastion\" dan \"Reaper\"; bos milikmu bisa dikendalikan.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Dunia yang hidup: prajuritmu meminta bantuan lewat radio (dengan hadiah), para pahlawan memberi misi, saat garis depan macet muncul operasi \"Titik Balik\". Kapsul, peti, dan serangan diluncurkan dari markas lewat portal langit.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Lebih cepat (satu frame sampai 2x lebih ringan), gamepad di semua mode, tata letak tablet, ensiklopedia seisi game, mode umpan balik — catatan dengan tangkapan layar hanya dengan satu tombol.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Semua teks baru diterjemahkan ke bahasa Uzbek, Tajik, Tionghoa, Spanyol, Portugis, dan Ibrani. Robo-ninja dan radio v7.9 tetap ada; v7.9 ada di menu \"🕘 Versi game\".",
"New in v8.15":"Baru di v8.15",
